package com.aurora.identity;

import com.aurora.audit.AuditService;
import com.aurora.security.WorkspaceContextHolder;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.SecureRandom;
import java.time.Instant;
import java.time.temporal.ChronoUnit;
import java.util.*;

@Service
public class WorkspaceMemberService {
 private static final SecureRandom RANDOM=new SecureRandom();
 private final WorkspaceInvitationRepository invitations; private final WorkspaceMembershipRepository memberships; private final UserAccountRepository users; private final AuditService audit; private final PasswordEncoder passwordEncoder;
 public WorkspaceMemberService(WorkspaceInvitationRepository i,WorkspaceMembershipRepository m,UserAccountRepository u,AuditService a,PasswordEncoder p){invitations=i;memberships=m;users=u;audit=a;passwordEncoder=p;}
 public record MemberView(Long membershipId,Long userId,Long workspaceId,String email,String displayName,WorkspaceRole role,Instant joinedAt){}
 public record InvitationView(Long id,String email,WorkspaceRole role,Instant createdAt,Instant expiresAt,String status){}
 public record CreatedInvitation(InvitationView invitation,String invitationToken){}
 @Transactional(readOnly=true) public List<MemberView> members(){return memberships.findAllByWorkspace_IdOrderByCreatedAtAsc(WorkspaceContextHolder.id()).stream().map(m->new MemberView(m.getId(),m.getUser().getId(),m.getWorkspace().getId(),m.getUser().getEmail(),m.getUser().getDisplayName(),m.getRole(),m.getCreatedAt())).toList();}
 @Transactional(readOnly=true) public List<InvitationView> invitations(){return invitations.findAllByWorkspace_IdOrderByCreatedAtDesc(WorkspaceContextHolder.id()).stream().map(this::view).toList();}
 @Transactional public CreatedInvitation invite(String email,WorkspaceRole role){WorkspaceContextHolder.requireAnyRole(WorkspaceRole.OWNER,WorkspaceRole.ADMIN);if(role==null||role==WorkspaceRole.OWNER)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Owner invitations are not available through this flow.");if(role==WorkspaceRole.ADMIN&&WorkspaceContextHolder.role()!=WorkspaceRole.OWNER)throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Only an owner can invite an administrator.");String normalized=UserAccount.normalizeEmail(email);if(users.findByEmail(normalized).filter(u->memberships.existsByUserIdAndWorkspaceId(u.getId(),WorkspaceContextHolder.id())).isPresent())throw new ResponseStatusException(HttpStatus.CONFLICT,"This person is already a workspace member.");if(invitations.findAllByWorkspace_IdAndEmail(WorkspaceContextHolder.id(),normalized).stream().anyMatch(i->i.isPending(Instant.now())))throw new ResponseStatusException(HttpStatus.CONFLICT,"A pending invitation already exists for this email address.");byte[] bytes=new byte[32];RANDOM.nextBytes(bytes);String token=Base64.getUrlEncoder().withoutPadding().encodeToString(bytes);WorkspaceInvitation invite=new WorkspaceInvitation(WorkspaceContextHolder.require(),normalized,role,hash(token),Instant.now().plus(7,ChronoUnit.DAYS));invitations.save(invite);audit.record("MEMBER_INVITED","WorkspaceInvitation",invite.getId().toString(),"Invited "+normalized+" as "+role);return new CreatedInvitation(view(invite),token);}
 @Transactional public MemberView acceptAndRegister(String token,String displayName,String password){
  WorkspaceInvitation invite=findPending(token);String email=invite.getEmail();if(users.existsByEmail(email))throw new ResponseStatusException(HttpStatus.CONFLICT,"An account already exists for this email. Sign in first, then accept the invitation.");
  if(password==null||password.length()<12||password.length()>72)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Password must contain 12 to 72 characters.");
  if(displayName==null||displayName.isBlank()||displayName.trim().length()>100)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"A valid display name is required.");
  UserAccount user=users.save(new UserAccount(email,passwordEncoder.encode(password),displayName));WorkspaceMembership membership=memberships.save(new WorkspaceMembership(invite.getWorkspace(),user,invite.getRole()));invite.accept();WorkspaceContextHolder.set(invite.getWorkspace(),invite.getRole());try{audit.record("MEMBER_JOINED","WorkspaceMembership",membership.getId().toString(),email+" joined as "+invite.getRole());}finally{WorkspaceContextHolder.clear();}return new MemberView(membership.getId(),user.getId(),invite.getWorkspace().getId(),email,user.getDisplayName(),membership.getRole(),membership.getCreatedAt());
 }
 private WorkspaceInvitation findPending(String token){if(token==null||token.length()<30||token.length()>200)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invitation token is invalid.");WorkspaceInvitation invite=invitations.findByTokenHash(hash(token)).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Invitation not found."));if(!invite.isPending(Instant.now()))throw new ResponseStatusException(HttpStatus.GONE,"Invitation has expired or is no longer active.");return invite;}
 @Transactional public MemberView accept(String token,UserAccount currentUser){WorkspaceInvitation invite=findPending(token);if(!invite.getEmail().equals(currentUser.getEmail()))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Sign in with the email address this invitation was sent to.");if(memberships.existsByUserIdAndWorkspaceId(currentUser.getId(),invite.getWorkspace().getId()))throw new ResponseStatusException(HttpStatus.CONFLICT,"You are already a member of this workspace.");WorkspaceMembership membership=memberships.save(new WorkspaceMembership(invite.getWorkspace(),currentUser,invite.getRole()));invite.accept();WorkspaceContextHolder.set(invite.getWorkspace(),invite.getRole());try{audit.record("MEMBER_JOINED","WorkspaceMembership",membership.getId().toString(),currentUser.getEmail()+" joined as "+invite.getRole());}finally{WorkspaceContextHolder.clear();}return new MemberView(membership.getId(),currentUser.getId(),invite.getWorkspace().getId(),currentUser.getEmail(),currentUser.getDisplayName(),membership.getRole(),membership.getCreatedAt());}
 @Transactional public void changeRole(Long membershipId,WorkspaceRole newRole){WorkspaceContextHolder.requireAnyRole(WorkspaceRole.OWNER,WorkspaceRole.ADMIN);WorkspaceMembership target=target(membershipId);WorkspaceRole actor=WorkspaceContextHolder.role();if(newRole==null)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Role is required.");if(actor==WorkspaceRole.ADMIN&&(target.getRole()==WorkspaceRole.OWNER||target.getRole()==WorkspaceRole.ADMIN||newRole==WorkspaceRole.OWNER||newRole==WorkspaceRole.ADMIN))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Administrators can only manage member and viewer roles.");if(actor!=WorkspaceRole.OWNER&&(newRole==WorkspaceRole.OWNER||newRole==WorkspaceRole.ADMIN))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Only an owner can assign owner or administrator roles.");if(target.getRole()==WorkspaceRole.OWNER&&newRole!=WorkspaceRole.OWNER&&memberships.countByWorkspace_IdAndRole(WorkspaceContextHolder.id(),WorkspaceRole.OWNER)<=1)throw new ResponseStatusException(HttpStatus.CONFLICT,"A workspace must always have at least one owner.");target.changeRole(newRole);audit.record("MEMBER_ROLE_CHANGED","WorkspaceMembership",membershipId.toString(),"Role changed to "+newRole);}
 @Transactional public void remove(Long membershipId){WorkspaceContextHolder.requireAnyRole(WorkspaceRole.OWNER,WorkspaceRole.ADMIN);WorkspaceMembership target=target(membershipId);WorkspaceRole actor=WorkspaceContextHolder.role();if(actor==WorkspaceRole.ADMIN&&(target.getRole()==WorkspaceRole.OWNER||target.getRole()==WorkspaceRole.ADMIN))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Administrators cannot remove owners or administrators.");if(target.getRole()==WorkspaceRole.OWNER&&memberships.countByWorkspace_IdAndRole(WorkspaceContextHolder.id(),WorkspaceRole.OWNER)<=1)throw new ResponseStatusException(HttpStatus.CONFLICT,"A workspace must always have at least one owner.");memberships.delete(target);audit.record("MEMBER_REMOVED","WorkspaceMembership",membershipId.toString(),"Removed "+target.getUser().getEmail());}
 @Transactional public void revoke(Long id){WorkspaceContextHolder.requireAnyRole(WorkspaceRole.OWNER,WorkspaceRole.ADMIN);WorkspaceInvitation invite=invitations.findById(id).filter(i->i.getWorkspace().getId().equals(WorkspaceContextHolder.id())).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Invitation not found."));if(!invite.isPending(Instant.now()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Invitation is no longer pending.");invite.revoke();audit.record("INVITATION_REVOKED","WorkspaceInvitation",id.toString(),"Revoked invitation for "+invite.getEmail());}
 private WorkspaceMembership target(Long id){return memberships.findById(id).filter(m->m.getWorkspace().getId().equals(WorkspaceContextHolder.id())).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Member not found."));}
 private InvitationView view(WorkspaceInvitation i){String status=i.getAcceptedAt()!=null?"ACCEPTED":i.getRevokedAt()!=null?"REVOKED":i.getExpiresAt().isBefore(Instant.now())?"EXPIRED":"PENDING";return new InvitationView(i.getId(),i.getEmail(),i.getRole(),i.getCreatedAt(),i.getExpiresAt(),status);}
 private static String hash(String token){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(token.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}
}
